// --- THE UNIT (A pure function) ---
function calculateTotal(price, taxRate) {
  if (price < 0) throw new Error("Price cannot be negative");
  return price + (price * taxRate);
}

// --- THE UNIT TESTS ---
// Testing the 'Happy Path'
function testHappyPath() {
  const result = calculateTotal(100, 0.1);
  console.assert(result === 110, "Expected 110");
}

// Testing the 'Edge Case' (Error handling)
function testNegativePrice() {
  try {
    calculateTotal(-50, 0.1);
    console.error("Test Failed: Should have thrown an error");
  } catch (err) {
    console.assert(err.message === "Price cannot be negative", "Expected specific error");
  }
}

testHappyPath();
testNegativePrice();
console.log("Unit tests passed!");
